import{_ as a,o as d,c as e,a2 as l}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"五、获客与转介绍","description":"获客是保险展业永恒的难题，转介绍是最高效、成本最低的获客方式。","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/05-获客转介绍.md","filePath":"副业/保险展业/05-获客转介绍.md","lastUpdated":1793203221000}'),i={name:"副业/保险展业/05-获客转介绍.md"};function s(n,t,r,o,h,p){return d(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="五、获客与转介绍" tabindex="-1">五、获客与转介绍 <a class="header-anchor" href="#五、获客与转介绍" aria-label="Permalink to &quot;五、获客与转介绍&quot;">​</a></h1><p>获客是保险展业永恒的难题，转介绍是最高效、成本最低的获客方式。</p><h2 id="_1-获客渠道" tabindex="-1">1. 获客渠道 <a class="header-anchor" href="#_1-获客渠道" aria-label="Permalink to &quot;1. 获客渠道&quot;">​</a></h2><h3 id="线下渠道" tabindex="-1">线下渠道 <a class="header-anchor" href="#线下渠道" aria-label="Permalink to &quot;线下渠道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>渠道</th><th>做法</th><th>适合人群</th></tr></thead><tbody><tr><td>缘故市场</td><td>先从熟人开始，亲戚朋友</td><td>刚入行的新人</td></tr><tr><td>活动获客</td><td>参加酒会、沙龙、讲座</td><td>建立圈层人脉</td></tr><tr><td>社区经营</td><td>社区活动、义工、兴趣社团</td><td>社区型代理人</td></tr><tr><td>异业合作</td><td>和房产、装修、教育机构合作</td><td>互惠互利</td></tr></tbody></table><h3 id="线上渠道" tabindex="-1">线上渠道 <a class="header-anchor" href="#线上渠道" aria-label="Permalink to &quot;线上渠道&quot;">​</a></h3><table tabindex="0"><thead><tr><th>渠道</th><th>做法</th><th>适合人群</th></tr></thead><tbody><tr><td>朋友圈</td><td>分享保险知识、案例</td><td>所有代理人</td></tr><tr><td>短视频</td><td>抖音/视频号科普保险</td><td>有镜头感的</td></tr><tr><td>公众号/文章</td><td>输出保险科普内容</td><td>文字能力强的</td></tr><tr><td>社群运营</td><td>微信群分享+答疑</td><td>有社群运营经验的</td></tr></tbody></table><h2 id="_2-转介绍——核心方法" tabindex="-1">2. 转介绍——核心方法 <a class="header-anchor" href="#_2-转介绍——核心方法" aria-label="Permalink to &quot;2. 转介绍——核心方法&quot;">​</a></h2><p>转介绍是所有客户来源里质量最高、成交率最高的。</p><h3 id="触发转介绍的时机" tabindex="-1">触发转介绍的时机 <a class="header-anchor" href="#触发转介绍的时机" aria-label="Permalink to &quot;触发转介绍的时机&quot;">​</a></h3><p><strong>签约时</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;恭喜您正式拥有保障！</span></span>
<span class="line"><span>其实身边像您这样情况的朋友应该不少，如果方便的话，</span></span>
<span class="line"><span>您可以介绍一两位，我可以免费帮他们做个保障分析，</span></span>
<span class="line"><span>也不一定要买保险，就当交个朋友。&quot;</span></span></code></pre></div><p><strong>理赔后</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;这次帮您理赔很顺利，说明保险确实帮到您了。</span></span>
<span class="line"><span>身边有朋友需要的话可以介绍给我，我提供一样的服务。&quot;</span></span></code></pre></div><p><strong>服务满意后</strong> 在客户表达满意时，顺势提出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;感谢您的认可！您身边有没有和朋友情况类似的，</span></span>
<span class="line"><span>我可以帮他们也看看。&quot;</span></span></code></pre></div><h3 id="让客户愿意转介绍的技巧" tabindex="-1">让客户愿意转介绍的技巧 <a class="header-anchor" href="#让客户愿意转介绍的技巧" aria-label="Permalink to &quot;让客户愿意转介绍的技巧&quot;">​</a></h3><ol><li><strong>服务超预期</strong>：理赔时多一步通知，出险后主动关心</li><li><strong>建立情感连接</strong>：记住客户家庭情况，节日问候</li><li><strong>给客户面子</strong>：介绍时说&quot;您的朋友眼光真好&quot;</li><li><strong>降低朋友压力</strong>：告诉客户&quot;就是做个免费分析，不买没关系&quot;</li></ol><h2 id="_3-客户分类管理" tabindex="-1">3. 客户分类管理 <a class="header-anchor" href="#_3-客户分类管理" aria-label="Permalink to &quot;3. 客户分类管理&quot;">​</a></h2><h3 id="abcd-分类法" tabindex="-1">ABCD 分类法 <a class="header-anchor" href="#abcd-分类法" aria-label="Permalink to &quot;ABCD 分类法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>标准</th><th>跟进策略</th></tr></thead><tbody><tr><td>A类</td><td>有需求+有信任+有购买力</td><td>重点跟进，尽快成交</td></tr><tr><td>B类</td><td>有需求+信任度一般</td><td>持续维护，建立信任</td></tr><tr><td>C类</td><td>有需求+暂无信任</td><td>持续输出价值内容</td></tr><tr><td>D类</td><td>无需求/已成交/不合适</td><td>节日维护即可</td></tr></tbody></table><h3 id="客户档案" tabindex="-1">客户档案 <a class="header-anchor" href="#客户档案" aria-label="Permalink to &quot;客户档案&quot;">​</a></h3><p>记录每个客户：</p><ul><li>基本信息（年龄、家庭、职业）</li><li>保障情况（已购险种、保额）</li><li>需求（担心什么）</li><li>跟进进度（下一步行动）</li><li>关键事件（生日、孩子升学等）</li></ul><h2 id="_4-日常展业习惯" tabindex="-1">4. 日常展业习惯 <a class="header-anchor" href="#_4-日常展业习惯" aria-label="Permalink to &quot;4. 日常展业习惯&quot;">​</a></h2><ul><li>每天添加 1-3 个新好友</li><li>每天朋友圈发布 1-2 条保险相关内容</li><li>每周至少和 3 个客户产生互动</li><li>每月参加 1-2 场活动</li><li>每月梳理客户名单，主动跟进 B/C 类客户</li></ul><h2 id="_5-注意事项" tabindex="-1">5. 注意事项 <a class="header-anchor" href="#_5-注意事项" aria-label="Permalink to &quot;5. 注意事项&quot;">​</a></h2><ul><li>❌ 不要群发广告，会被拉黑</li><li>❌ 不要频繁刷屏发产品信息</li><li>❌ 不要只联系客户要转介绍，平时不维护</li><li>✅ 持续输出价值内容，建立专业形象</li><li>✅ 把每个客户当朋友真诚对待</li></ul>`,28)])])}const b=a(i,[["render",s]]);export{u as __pageData,b as default};
